package com.sphere.core.clhep.geometry;

import com.sphere.core.clhep.vector.Hep3Vector;

/**
 * CLHEP's HepGeom::Normal3D&lt;double&gt; (Geometry/Normal3D.h, Normal3D.cc): the normal of a surface, which a
 * transformation turns by the cofactors of its matrix (normals stay normal under scaling). Generated by
 * gen_geometry.py.
 */
public class Normal3D extends BasicVector3D {

    public Normal3D() {
        super();
    }

    public Normal3D(double x1, double y1, double z1) {
        super(x1, y1, z1);
    }

    /** From the first three of an array. */
    public Normal3D(float[] a) {
        super(a[0], a[1], a[2]);
    }

    public Normal3D(double[] a) {
        super(a[0], a[1], a[2]);
    }

    public Normal3D(BasicVector3DF v) {
        super(v);
    }

    public Normal3D(Hep3Vector v) {
        super(v.x(), v.y(), v.z());
    }

    public Normal3D(BasicVector3D v) {
        super(v);
    }

    /** This normal transformed by m: the cofactor matrix of m's 3x3 part. */
    public Normal3D transform(Transform3D m) {
        final double vx = x();
        final double vy = y();
        final double vz = z();
        final double xx = m.xx(), xy = m.xy(), xz = m.xz();
        final double yx = m.yx(), yy = m.yy(), yz = m.yz();
        final double zx = m.zx(), zy = m.zy(), zz = m.zz();
        set(((yy * zz - yz * zy) * vx + (yz * zx - yx * zz) * vy + (yx * zy - yy * zx) * vz),
            ((zy * xz - zz * xy) * vx + (zz * xx - zx * xz) * vy + (zx * xy - zy * xx) * vz),
            ((xy * yz - xz * yy) * vx + (xz * yx - xx * yz) * vy + (xx * yy - xy * yx) * vz));
        return this;
    }
}
